/* Deterministic local API practice. No network or persistent storage. */
(()=>{const form=document.getElementById('aimApiLab');if(!form)return;const input=document.getElementById('aimApiInput'),out=document.getElementById('aimApiOutput'),count=document.getElementById('aimApiCount'),seen=new Map();const samples=[{"event_id":"E01","lead_id":"L01","source":"ads"},{"event_id":"E01","lead_id":"L01","source":"ads"},{"event_id":"E02","lead_id":"","source":"email"},{"event_id":"E03","lead_id":"L02","source":"email"}];let i=0;const show=(code,msg)=>{out.textContent=code+' · '+msg;count.textContent='Số sự kiện đã nhận: '+seen.size;};form.addEventListener('submit',e=>{e.preventDefault();let v;try{v=JSON.parse(input.value);}catch{return show(400,'JSON sai cú pháp');}if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).length!==3||!Object.hasOwn(v,'event_id')||!Object.hasOwn(v,'lead_id')||!Object.hasOwn(v,'source')||typeof v.event_id!=='string'||!/^E[0-9]{2,6}$/.test(v.event_id)||typeof v.lead_id!=='string'||!/^L[0-9]{2,6}$/.test(v.lead_id)||!['ads','email','organic'].includes(v.source))return show(400,'Thiếu trường hoặc sai ID/nguồn theo hợp đồng lab.');const fingerprint=JSON.stringify([v.lead_id,v.source]);if(seen.has(v.event_id)){return seen.get(v.event_id)===fingerprint?show(200,'Sự kiện đã nhận; không ghi thêm.'):show(409,'Cùng event_id nhưng dữ liệu khác; cần xem xét.');}if(seen.size>=1000)return show(429,'Lab giới hạn 1000 sự kiện. Đặt lại để tiếp tục.');seen.set(v.event_id,fingerprint);show(201,'Đã nhận sự kiện mới (mô phỏng).');});document.getElementById('aimApiNext').onclick=()=>{i=(i+1)%samples.length;input.value=JSON.stringify(samples[i],null,2);};document.getElementById('aimApiReset').onclick=()=>{i=0;seen.clear();input.value=JSON.stringify(samples[i],null,2);out.textContent='Chưa nhận sự kiện.';count.textContent='Số sự kiện đã nhận: 0';};})();
